css:
.col-1{
      width: 50%; float: left; font-weight: bold;
      }
.col-2{
width: 50%; float: right; font-weight: bold;}	
p{ font-size: 12px; }

table, th, td {
  border: 1px solid black;
}

html:
{%- from "templates/print_formats/standard_macros.html" import add_header -%}

{% set g = {} %}

{# ========================================================= #}
{# CHECK WHETHER THE SELECTED COURSE ISSUES A STUDENT CARD   #}
{# ========================================================= #}

{% set will_card_issue = frappe.db.get_value(
    "Course",
    doc.course,
    "custom_will_card_issue"
) or 0 %}


<div>
  {% if doc.students %}

    {% set selected_customer = doc.custom_customer or doc.customer %}

    {% set customers = [] %}

    {% if selected_customer %}

      {% set customers = [selected_customer] %}

    {% else %}

      {% for i in doc.students %}

        {% if i.customer_name and i.customer_name not in customers %}
          {% set _ = customers.append(i.customer_name) %}
        {% endif %}

      {% endfor %}

    {% endif %}


    {# ------------------------------------------------------ #}
    {# COURSE DATE RANGE                                      #}
    {# ------------------------------------------------------ #}

    {% set start = frappe.utils.getdate(
        doc.custom_from_date or doc.from_date
    ) %}

    {% set end = frappe.utils.getdate(
        doc.custom_to_date or doc.to_date
    ) %}

    {% set total_days = frappe.utils.date_diff(end, start) + 1 %}

    {% set dates = [] %}

    {% for i in range(total_days) %}

      {% set dt = frappe.utils.add_days(start, i) %}

      {% set _ = dates.append(dt) %}

    {% endfor %}


    {# ------------------------------------------------------ #}
    {# CUSTOMER LOOP                                          #}
    {# ------------------------------------------------------ #}

    {% for customer in customers %}

      {% set title = customer if customer else "&nbsp;" %}


      {# ---------------------------------------------------- #}
      {# GET UNIQUE PURCHASE ORDERS FOR CUSTOMER              #}
      {# ---------------------------------------------------- #}

      {% set po_list = [] %}

      {% for k in doc.students if k.customer_name == customer %}

        {% set student_po = frappe.db.get_value(
            "Student",
            k.student,
            "custom_customer_purchase_order"
        ) %}

        {% if student_po and student_po not in po_list %}
          {% set _ = po_list.append(student_po) %}
        {% endif %}

      {% endfor %}


      {% if po_list | length == 0 %}
        {% set po_list = [None] %}
      {% endif %}


      {# ---------------------------------------------------- #}
      {# PURCHASE ORDER LOOP                                  #}
      {# ---------------------------------------------------- #}

      {% for po in po_list %}


        {# -------------------------------------------------- #}
        {# CHECK WHETHER SECONDARY COMPANY COLUMN IS NEEDED   #}
        {# -------------------------------------------------- #}

        {% set secondary_hits = [] %}

        {% for k in doc.students if k.customer_name == customer %}

          {% set student_po = frappe.db.get_value(
              "Student",
              k.student,
              "custom_customer_purchase_order"
          ) %}

          {% if student_po == po %}

            {% set secondary_customer = frappe.db.get_value(
                "Student",
                k.student,
                "custom_secondary_customer"
            ) %}

            {% if secondary_customer %}
              {% set _ = secondary_hits.append(1) %}
            {% endif %}

          {% endif %}

        {% endfor %}

        {% set show_secondary = secondary_hits | length > 0 %}


        <div style="page-break-before: always;">


          {# ================================================= #}
          {# PAGE HEADER                                       #}
          {# ================================================= #}

          {% set letter_head = frappe.get_doc(
              "Letter Head",
              "Letter Head New"
          ) %}

          {% if letter_head %}
            <div class="letter-head">
              {{ letter_head.content }}
            </div>
          {% endif %}


          <div
            class="row"
            style="
              text-align: center;
              margin-top: 0;
            "
          >
            <h2>
              <b>
                <u>ATTENDENCE SHEET</u>
              </b>
            </h2>
          </div>


          <div
            style="
              margin-top: 2%;
              display: flex;
              gap: 24px;
            "
          >

            <div class="col-1">

              <p>
                <b>Sheet No :</b>
                {{ doc.name }}
              </p>

              <p>
                <b>Date :</b>
                {{ frappe.utils.formatdate(doc.creation) }}
              </p>

              <p>
                <b>Course Start Date :</b>
                {{ frappe.utils.formatdate(doc.from_date) }}
              </p>

              <p>
                <b>Course End Date :</b>
                {{ frappe.utils.formatdate(doc.to_date) }}
              </p>

            </div>


            <div class="col-2">

              <p>
                <b>Confirmation Type :</b>
                {{ po or "" }}
              </p>

              <p>
                <b>Training :</b>
                {{ doc.course }}
              </p>

              <p>
                <b>Course Location :</b>
                {{ doc.custom_course_location_name }}
              </p>

            </div>

          </div>


          {# ================================================= #}
          {# CUSTOMER AND PURCHASE ORDER HEADING               #}
          {# ================================================= #}

          <table
            width="100%"
            style="
              margin-top: 12px;
              border: none !important;
              border-collapse: collapse;
            "
          >

            <tr style="border: none !important;">

              <td
                style="
                  padding: 0;
                  border: none !important;
                  text-align: left;
                "
              >

                <span
                  style="
                    font-size: 16px;
                    font-weight: 800;
                  "
                >
                  {{ title }}
                </span>

                {% if po %}

                  <span
                    style="
                      font-size: 16px;
                      font-weight: 800;
                    "
                  >
                    — PO: {{ po }}
                  </span>

                {% endif %}

              </td>

            </tr>

          </table>


          {# ================================================= #}
          {# ATTENDANCE TABLE                                  #}
          {# ================================================= #}

          <table
            width="100%"
            style="
              width: 100%;
              margin-top: 5%;
              border: 1px solid #000;
              border-collapse: collapse;
              table-layout: auto;
            "
          >

            <thead>

              <tr>

                <th
                  style="
                    border: 1px solid #000;
                    padding: 4px;
                    text-align: center;
                    white-space: nowrap;
                  "
                >
                  S.No
                </th>

                <th
                  style="
                    border: 1px solid #000;
                    padding: 4px;
                    text-align: center;
                  "
                >
                  Name Of the Delegate
                </th>

                <th
                  style="
                    border: 1px solid #000;
                    padding: 4px;
                    text-align: center;
                    white-space: nowrap;
                  "
                >
                  PO No
                </th>


                {% if show_secondary %}

                  <th
                    style="
                      border: 1px solid #000;
                      padding: 4px;
                      text-align: center;
                    "
                  >
                    Secondary Company
                  </th>

                {% endif %}


                <th
                  style="
                    border: 1px solid #000;
                    padding: 4px;
                    text-align: center;
                  "
                >
                  Nationality
                </th>

                <th
                  style="
                    border: 1px solid #000;
                    padding: 4px;
                    text-align: center;
                    white-space: nowrap;
                  "
                >
                  DOB
                </th>


                {% for d in dates %}

                  <th
                    style="
                      border: 1px solid #000;
                      padding: 4px;
                      text-align: center;
                      white-space: nowrap;
                    "
                  >
                    {{ frappe.utils.formatdate(d, "MMM dd") }}
                  </th>

                {% endfor %}


                <th
                  style="
                    border: 1px solid #000;
                    padding: 4px;
                    text-align: center;
                  "
                >
                  Result
                </th>


                {# ------------------------------------------- #}
                {# CARD RECEIVED HEADER                        #}
                {# Show only when checkbox is checked          #}
                {# ------------------------------------------- #}

                {% if will_card_issue | int == 1 %}

                  <th
                    style="
                      border: 1px solid #000;
                      padding: 4px;
                      text-align: center;
                      white-space: nowrap;
                    "
                  >
                    Card Received
                  </th>

                {% endif %}

              </tr>

            </thead>


            <tbody>

              {% set serial = [] %}


              {% for k in doc.students if k.customer_name == customer %}


                {% set student_po = frappe.db.get_value(
                    "Student",
                    k.student,
                    "custom_customer_purchase_order"
                ) %}


                {% if
                    (po and student_po == po)
                    or
                    (not po and not student_po)
                %}


                  {% set _ = serial.append(1) %}


                  <tr>


                    {# --------------------------------------- #}
                    {# SERIAL NUMBER                           #}
                    {# --------------------------------------- #}

                    <td
                      style="
                        border: 1px solid #000;
                        padding: 4px;
                        text-align: center;
                        vertical-align: middle;
                      "
                    >
                      {{ serial | length }}
                    </td>


                    {# --------------------------------------- #}
                    {# STUDENT NAME                            #}
                    {# --------------------------------------- #}

                    <td
                      style="
                        border: 1px solid #000;
                        padding: 4px;
                        vertical-align: middle;
                      "
                    >
                      {{ k.student_name }}
                    </td>


                    {# --------------------------------------- #}
                    {# PURCHASE ORDER                          #}
                    {# --------------------------------------- #}

                    <td
                      style="
                        border: 1px solid #000;
                        padding: 4px;
                        vertical-align: middle;
                      "
                    >
                      {{ student_po or "" }}
                    </td>


                    {# --------------------------------------- #}
                    {# SECONDARY COMPANY                       #}
                    {# --------------------------------------- #}

                    {% if show_secondary %}

                      {% set secondary_customer = frappe.db.get_value(
                          "Student",
                          k.student,
                          "custom_secondary_customer"
                      ) %}

                      <td
                        style="
                          border: 1px solid #000;
                          padding: 4px;
                          vertical-align: middle;
                        "
                      >
                        {{ secondary_customer or "" }}
                      </td>

                    {% endif %}


                    {# --------------------------------------- #}
                    {# NATIONALITY                             #}
                    {# --------------------------------------- #}

                    {% set nationality = frappe.db.get_value(
                        "Student",
                        k.student,
                        "nationality"
                    ) %}

                    <td
                      style="
                        border: 1px solid #000;
                        padding: 4px;
                        vertical-align: middle;
                      "
                    >
                      {{ nationality or "" }}
                    </td>


                    {# --------------------------------------- #}
                    {# DATE OF BIRTH                           #}
                    {# --------------------------------------- #}

                    {% set dob = frappe.db.get_value(
                        "Student",
                        k.student,
                        "date_of_birth"
                    ) %}

                    <td
                      style="
                        border: 1px solid #000;
                        padding: 4px;
                        text-align: center;
                        vertical-align: middle;
                        white-space: nowrap;
                      "
                    >

                      {% if dob %}
                        {{ frappe.utils.formatdate(dob) }}
                      {% endif %}

                    </td>


                    {# ======================================= #}
                    {# ATTENDANCE SIGNATURE FOR EACH DATE      #}
                    {# ======================================= #}

                    {% for d in dates %}


                      {% set att_name = frappe.db.get_value(
                          "Student Attendance",
                          {
                              "date": d,
                              "student_group": doc.name,
                              "student": k.student,
                              "docstatus": 1
                          },
                          "name"
                      ) %}


                      {% set sig1 = None %}
                      {% set sig2 = None %}


                      {% if att_name %}

                        {% set sig1 = frappe.db.get_value(
                            "Student Attendance",
                            att_name,
                            "custom_student_signature1"
                        ) %}

                        {% set sig2 = frappe.db.get_value(
                            "Student Attendance",
                            att_name,
                            "custom_student_signature"
                        ) %}

                      {% endif %}


                      <td
                        style="
                          height: 32px;
                          border: 1px solid #000;
                          padding: 4px;
                          text-align: center;
                          vertical-align: middle;
                        "
                      >

                        {% if sig1 %}

                          <img
                            src="{{ sig1 }}"
                            alt="Student Signature"
                            style="
                              width: 60px;
                              max-width: 60px;
                              height: 25px;
                              max-height: 25px;
                              display: block;
                              margin: 0 auto;
                              object-fit: contain;
                            "
                          >

                        {% elif sig2 %}

                          <img
                            src="{{ sig2 }}"
                            alt="Student Signature"
                            style="
                              width: 60px;
                              max-width: 60px;
                              height: 25px;
                              max-height: 25px;
                              display: block;
                              margin: 0 auto;
                              object-fit: contain;
                            "
                          >

                        {% endif %}

                      </td>

                    {% endfor %}


                    {# --------------------------------------- #}
                    {# RESULT                                  #}
                    {# --------------------------------------- #}

                    <td
                      style="
                        border: 1px solid #000;
                        padding: 4px;
                        text-align: center;
                        vertical-align: middle;
                      "
                    >
                    </td>


                    {# ======================================= #}
                    {# CARD RECEIVED SIGNATURE                 #}
                    {# Only show and query when checkbox marked #}
                    {# ======================================= #}

                    {% if will_card_issue | int == 1 %}


                      {% set card_signature = None %}


                      {% set student_card_name = frappe.db.get_value(
                          "Student Card",
                          {
                              "student_group": doc.name,
                              "student": k.student,
                              "docstatus": 1
                          },
                          "name"
                      ) %}


                      {% if student_card_name %}

                        {% set card_signature = frappe.db.get_value(
                            "Student Card",
                            student_card_name,
                            "student_signature"
                        ) %}

                      {% endif %}


                      <td
                        style="
                          height: 32px;
                          border: 1px solid #000;
                          padding: 4px;
                          text-align: center;
                          vertical-align: middle;
                        "
                      >

                        {% if card_signature %}

                          <img
                            src="{{ card_signature }}"
                            alt="Card Received Signature"
                            style="
                              width: 80px;
                              max-width: 80px;
                              height: 30px;
                              max-height: 30px;
                              display: block;
                              margin: 0 auto;
                              object-fit: contain;
                            "
                          >

                        {% endif %}

                      </td>


                    {% endif %}


                  </tr>


                {% endif %}


              {% endfor %}


            </tbody>

          </table>


          {# ================================================= #}
          {# INSTRUCTOR INFORMATION AND SIGNATURE              #}
          {# ================================================= #}

          <div style="width: 100%; overflow: auto;">


            <div
              style="
                float: left;
                width: 50%;
                margin-top: 5%;
              "
            >

              {% if doc.instructors %}

                {% for instructor_row in doc.instructors %}

                  <p>
                    INSTRUCTOR'S NAME:
                    <b>{{ instructor_row.instructor_name }}</b>
                  </p>

                {% endfor %}

              {% endif %}


              <p>
                Date:
                {{ frappe.utils.formatdate(
                    doc.to_date,
                    "dd-MM-yyyy"
                ) }}
              </p>

            </div>


            {# ------------------------------------------------ #}
            {# GET FIRST INSTRUCTOR SAFELY                      #}
            {# ------------------------------------------------ #}

            {% set first_instructor_row = (
                doc.instructors[0]
                if doc.instructors
                and doc.instructors | length > 0
                else None
            ) %}


            {% if
                first_instructor_row
                and first_instructor_row.instructor
            %}


              {% set instructor_doc = frappe.get_doc(
                  "Instructor",
                  first_instructor_row.instructor
              ) %}


              {% set instructor_image =
                  instructor_doc.signature_image
                  or instructor_doc.image
                  or instructor_doc.photo
              %}


              {% if instructor_image %}

                {% set instructor_image_url =
                    frappe.utils.get_url(instructor_image)
                %}


                <div
                  style="
                    float: right;
                    width: 30%;
                    margin-top: 5%;
                    text-align: right;
                  "
                >

                  <img
                    src="{{ instructor_image_url }}"
                    alt="Instructor Signature"
                    style="
                      width: 120px;
                      height: 70px;
                      object-fit: contain;
                    "
                  >

                  <br>

                  <p
                    style="
                      margin: 4px 0 0;
                      font-weight: 600;
                    "
                  >
                    SIGNATURE:
                  </p>

                </div>


              {% endif %}


            {% endif %}


          </div>


        </div>


      {% endfor %}

    {% endfor %}

  {% endif %}

</div>


<footer class="print-footer">

  <div class="col-md-12">

    <div class="row">

      <div
        id="footer-html"
        class="hidden-pdf"
      >

        <div class="letter-head-footer">

          <table width="100%">

            <tr>

              <th>
                Po Box 132435, ICAD, Behind Dalma Mall Block B
                Mussaffah, Abu Dhabi, U.A.E
              </th>

            </tr>

          </table>

        </div>

      </div>

    </div>

  </div>

</footer>
